 * Types for Claude Code transcript parsing.
 *
 * Claude Code writes conversation transcripts as JSONL files. Each line is a
 * single entry with a `type` discriminator ('user' | 'assistant' | 'progress' |
 * 'queue-operation'). Assistant/user entries carry an Anthropic-style
 * `message: {role, content}` envelope where `content` is either a plain string
 * or an array of content blocks (text / tool_use / tool_result / thinking).
 *
 * Sub-agent activity is represented two ways:
 *   - inline `progress` entries whose `data.message` embeds a nested transcript
 *     entry, linked to the parent Task tool call by `parentToolUseID`.
 *   - a separate `subagents/agent-<agentId>.jsonl` file, referenced from the
 *     Task tool result's `toolUseResult.agentId`.
 */

/**
 * A single content block inside an Anthropic-format message. The `type`
 * discriminator selects the meaningful fields (text / tool_use / tool_result).
 */
export interface ContentBlock {
  type: string;
  text?: string;
  /** tool_use */
  id?: string;
  name?: string;
  input?: Record<string, any>;
  /** tool_result */
  tool_use_id?: string;
  content?: any;
  is_error?: boolean;
  [key: string]: any;
}

/**
 * Token usage reported by the Anthropic API on assistant messages.
 */
export interface Usage {
  input_tokens?: number;
  output_tokens?: number;
  cache_creation_input_tokens?: number;
  cache_read_input_tokens?: number;
  [key: string]: any;
}

/**
 * Anthropic-style message envelope carried on user/assistant entries.
 */
export interface Message {
  role?: string;
  content?: string | ContentBlock[];
  model?: string;
  usage?: Usage;
  [key: string]: any;
}

/**
 * Structured tool result metadata attached to a user entry that carries a
 * tool_result block. For Task tool calls, `agentId` points at the sub-agent's
 * separate transcript file.
 */
export interface ToolUseResult {
  status?: string;
  agentId?: string;
  totalDurationMs?: number;
  success?: boolean;
  commandName?: string;
  [key: string]: any;
}

/**
 * Payload of an inline `progress` entry emitted while a sub-agent runs.
 */
export interface ProgressData {
  type: string;
  agentId: string;
  prompt: string;
  message: TranscriptEntry;
  [key: string]: any;
}

/**
 * A single entry in a Claude Code JSONL transcript.
 */
export interface TranscriptEntry {
  type: string;
  message?: Message;
  timestamp?: string | number;
  sessionId?: string;
  agentId?: string;
  version?: string;
  permissionMode?: string;
  isCompactSummary?: boolean;
  toolUseResult?: ToolUseResult;

  /** progress entries */
  parentToolUseID?: string;
  toolUseID?: string;
  data?: ProgressData;

  /** queue-operation entries */
  operation?: string;
  content?: string;

  [key: string]: any;
}

/**
 * Stop hook input received via stdin from Claude Code.
 */
export interface StopHookInput {
  session_id: string;
  transcript_path: string | null;
  cwd: string;
  hook_event_name: string;
  [key: string]: any;
}
