 * Transcript parsing utilities for Claude Code JSONL files.
 *
 * Claude Code writes each conversation entry as one JSON object per line. These
 * helpers read and parse those files and provide the small, pure primitives the
 * tracing layer builds on: timestamp conversion, text extraction, and locating
 * the "real" user prompt / final assistant response within a transcript.
 */

import { readFileSync } from 'node:fs';
import type { ContentBlock, TranscriptEntry } from './types.js';

export const NANOSECONDS_PER_MS = 1e6;
export const NANOSECONDS_PER_S = 1e9;

/** Read and parse a Claude Code JSONL transcript file. */
export function readTranscript(filePath: string): TranscriptEntry[] {
  const content = readFileSync(filePath, 'utf-8');
  return content
    .split('\n')
    .filter((line) => line.trim())
    .map((line) => JSON.parse(line) as TranscriptEntry);
}

/**
 * Convert a timestamp to nanoseconds since the Unix epoch.
 *
 * ISO date strings are parsed via `Date` and scaled to nanoseconds. Numeric
 * values are treated as nanoseconds if `>= 1e13`, milliseconds if `>= 1e10`, or
 * Unix seconds otherwise. Returns null for null / undefined / empty string
 * inputs and for strings that are not valid dates.
 */
export function parseTimestampToNs(ts: string | number | null | undefined): number | null {
  if (ts === null || ts === undefined || ts === '') {
    return null;
  }

  if (typeof ts === 'number') {
    if (ts >= 1e13) {
      return Math.floor(ts);
    }
    if (ts >= 1e10) {
      return Math.floor(ts * NANOSECONDS_PER_MS);
    }
    return Math.floor(ts * NANOSECONDS_PER_S);
  }

  const ms = new Date(ts).getTime();
  if (isNaN(ms)) {
    return null;
  }
  return Math.floor(ms * NANOSECONDS_PER_MS);
}

/**
 * Extract plain text from a message content value. A string is returned
 * unchanged; an array of content blocks has the `text` fields of its
 * `type: 'text'` blocks joined with newlines. Anything else yields ''.
 */
export function extractTextContent(
  content: string | Array<{ type: string; text?: string; [key: string]: any }>,
): string {
  if (typeof content === 'string') {
    return content;
  }
  if (Array.isArray(content)) {
    return content
      .filter((part) => part && (part as ContentBlock).type === 'text')
      .map((part) => (part as ContentBlock).text ?? '')
      .join('\n');
  }
  return '';
}

/**
 * Find the index of the last "real" user message in the transcript.
 *
 * Skips entries that are not genuine user prompts:
 *   - user entries whose message content is an array of tool_result blocks,
 *   - entries marked with `isCompactSummary: true`,
 *   - skill-injection messages whose text content starts with 'Base directory:'.
 *
 * Returns null for an empty transcript or when no real user message exists.
 */
export function findLastUserMessageIndex(entries: TranscriptEntry[]): number | null {
  for (let i = entries.length - 1; i >= 0; i--) {
    const entry = entries[i];
    if (entry.type !== 'user') {
      continue;
    }
    if (entry.isCompactSummary === true) {
      continue;
    }

    const content = entry.message?.content;
    if (
      Array.isArray(content) &&
      content.length > 0 &&
      content[0] &&
      content[0].type === 'tool_result'
    ) {
      continue;
    }

    const text = extractTextContent(content ?? '');
    if (text.startsWith('Base directory:')) {
      continue;
    }

    return i;
  }
  return null;
}

/**
 * Search from `startIndex` onward for the last assistant entry that has text
 * content and return its extracted text, or null if none exists.
 */
export function findFinalAssistantResponse(
  entries: TranscriptEntry[],
  startIndex: number,
): string | null {
  let finalResponse: string | null = null;
  for (let i = startIndex; i < entries.length; i++) {
    const entry = entries[i];
    if (entry.type !== 'assistant') {
      continue;
    }
    const text = extractTextContent(entry.message?.content ?? '');
    if (text.trim()) {
      finalResponse = text;
    }
  }
  return finalResponse;
}
