const PERMISSION_MODE_KEY = 'mlflow.trace.permission_mode';
const CLAUDE_CODE_VERSION_KEY = 'mlflow.claude_code_version';

/** A tool_result paired with the user entry that carried it. */
interface ToolResult {
  content: any;
  isError: boolean;
  entry: TranscriptEntry;
