  createLlmAndToolSpans(rootSpan, transcript, lastUserIdx + 1, toolResults, ctx);

  const finalResponse = findFinalAssistantResponse(transcript, lastUserIdx + 1);

  // Conversation end time: last entry timestamp, falling back to a fixed
  // window after the start when unavailable or non-increasing.
  const lastEntry = transcript[transcript.length - 1];
  let convEndNs = parseTimestampToNs(lastEntry.timestamp);
  if (convEndNs == null || (convStartNs != null && convEndNs <= convStartNs)) {
    convEndNs = convStartNs != null ? convStartNs + 10 * NANOSECONDS_PER_S : null;
  }

