  const outputs: Record<string, any> = { status: 'completed' };
  if (finalResponse != null) {
    outputs.response = finalResponse;
  }
  rootSpan.end({
    outputs,
    ...(convEndNs != null ? { endTimeNs: convEndNs } : {}),
