 * integrations don't have, so we mutate the trace through InMemoryTraceManager
 * directly — the same pattern used by the codex/opencode/qwen integrations.
 */
function applyTraceMetadata(
  rootSpan: LiveSpan,
  transcript: TranscriptEntry[],
  sessionId: string,
  userPromptText: string,
  finalResponse: string | null,
